26	            | Stmt::ClassDef(_)
27	            | Stmt::While(_)
28	            | Stmt::For(_)
29	            | Stmt::Match(_)
30	            | Stmt::With(_)
31	            | Stmt::If(_)
32	            | Stmt::Try(_)
33	    )
34	}
