36	fn is_iterable_initializer<F>(id: &str, is_builtin: F) -> bool
37	where
38	    F: Fn(&str) -> bool,
39	{
40	    matches!(id, "list" | "tuple" | "set" | "dict" | "frozenset") && is_builtin(id)
41	}
